def windDir(deg: int) -> str:
    directions = [
        (0, 44, "N"),
        (45, 89, "NE"),
        (90, 134, "E"),
        (135, 179, "SE"),
        (180, 224, "S"),
        (225, 269, "SW"),
        (270, 314, "W"),
        (315, 359, "NW")
    ]
    for lhs, rhs, name in directions:
        if lhs <= deg <= rhs:
            return name
    return "N"  # fallback for 0-44 wrap-around (though 0-44 already covered)

def main():
    test_cases = [0, 45, 90, 135, 180, 225, 270, 315, 359, 22, 300, 224, 269]
    for deg in test_cases:
        print(windDir(deg))

if __name__ == "__main__":
    main()

