#include <stdio.h>
#include <string.h>
#include <stdlib.h>

const char* windDir(int deg) {
    const char* directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    int bounds[] = {0, 45, 90, 135, 180, 225, 270, 315, 360};

    for (int i = 0; i < 8; i++) {
        if (deg >= bounds[i] && deg < bounds[i+1]) {
            return directions[i];
        }
    }

    return "N";
}

int main() {
    int test_cases[] = {0, 44, 45, 89, 90, 134, 135, 179, 180, 224, 225, 269, 270, 314, 315, 359, 360, -1, 720};
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        int deg = test_cases[i];
        if (deg < 0 || deg >= 360) {
            deg = (deg % 360 + 360) % 360;
        }
        printf("%d -> %s\n", test_cases[i], windDir(deg));
    }

    return 0;
}

