import java.util.*;

public class Solution {
    public static String windDir(int deg) {
        if (deg < 0 || deg > 359) {
            return "Invalid";
        }
        String[] directions = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
        int[] bounds = {45, 90, 135, 180, 225, 270, 315, 360};
        for (int i = 0; i < bounds.length; i++) {
            if (deg < bounds[i]) {
                return directions[i];
            }
        }
        return "N";
    }

    public static void main(String[] args) {
        System.out.println(windDir(0));
        System.out.println(windDir(44));
        System.out.println(windDir(90));
        System.out.println(windDir(179));
        System.out.println(windDir(359));
    }
}
